CREATE TABLE "ConventionalDraft" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL UNIQUE, "status" TEXT NOT NULL, "orderSnapshotId" TEXT, "orderHash" TEXT, "contractVersion" TEXT NOT NULL, "completedAt" TEXT, "createdAt" TEXT NOT NULL, FOREIGN KEY ("seasonId") REFERENCES "Season"("id"));
CREATE TABLE "DraftOrderEntry" ("id" TEXT NOT NULL PRIMARY KEY, "conventionalDraftId" TEXT NOT NULL, "orderPosition" INTEGER NOT NULL, "seasonTeamId" TEXT NOT NULL, "remainingBalance" INTEGER NOT NULL, FOREIGN KEY ("conventionalDraftId") REFERENCES "ConventionalDraft"("id"), FOREIGN KEY ("seasonTeamId") REFERENCES "SeasonTeam"("id"), UNIQUE("conventionalDraftId", "orderPosition"), UNIQUE("conventionalDraftId", "seasonTeamId"));
CREATE TABLE "DraftOrderTieDecision" ("id" TEXT NOT NULL PRIMARY KEY, "conventionalDraftId" TEXT NOT NULL, "balance" INTEGER NOT NULL, "participantTeamIdsJson" TEXT NOT NULL, "precedenceTeamIdsJson" TEXT NOT NULL, "method" TEXT NOT NULL, "note" TEXT, "decidedAt" TEXT NOT NULL, FOREIGN KEY ("conventionalDraftId") REFERENCES "ConventionalDraft"("id"), UNIQUE("conventionalDraftId", "balance"));
CREATE TABLE "DraftPick" ("id" TEXT NOT NULL PRIMARY KEY, "conventionalDraftId" TEXT NOT NULL, "overallPick" INTEGER NOT NULL, "roundNumber" INTEGER NOT NULL, "orderPosition" INTEGER NOT NULL, "seasonTeamId" TEXT NOT NULL, "playerId" TEXT NOT NULL, "active" INTEGER NOT NULL DEFAULT 1, "supersededAt" TEXT, "createdAt" TEXT NOT NULL, FOREIGN KEY ("conventionalDraftId") REFERENCES "ConventionalDraft"("id"), FOREIGN KEY ("seasonTeamId") REFERENCES "SeasonTeam"("id"), UNIQUE("conventionalDraftId", "overallPick"), UNIQUE("conventionalDraftId", "playerId"));
UPDATE "SchemaMetadata" SET "version"=4, "applicationVersion"='0.4.0' WHERE "singleton"=1;
